if ("--watch" in $arguments) or ("-w" in $arguments) { error make {msg: "Native watch is disabled; use sayt launch --watch for Docker"} }
let os = (match $nu.os-info.name { "macos" => "macos", "windows" => "windows", _ => "linux" })
