  } | ignore
  for d in ($ep | parse -r 'grep -rqE \x27\[\[:space:\]\](?<k>[^=]+)=\x22(?<v>[^\x22]*)\x22\x27 \x27[^\x27]+\x27 --include=\x27\*\.html\x27 \|\| \{ echo \x27(?<msg>[^\x27]+)\x27') {
    mut matched = false
    for f in (glob ($tree_dir | path join "**/*.html" | str replace -a (char -u 5c) "/")) {
      let raw = (open --raw $f)
      let pat = ('(\s' + $d.k + '=)\x22[^\x22]*\x22')
